describe('Notification Click Navigation', () => {
    beforeEach(() => {
        cy.visit('/notifications'); // Adjust the URL as necessary
    });

    it('should navigate to the related content when a notification is clicked', () => {
        cy.get('.notification') // Adjust the selector as necessary
            .first()
            .click();

        cy.url().should('include', '/related-content'); // Adjust the URL as necessary
        cy.get('.related-content-title').should('be.visible'); // Adjust the selector as necessary
    });

    it('should not navigate if the notification is disabled', () => {
        cy.get('.notification.disabled') // Adjust the selector as necessary
            .first()
            .click();

        cy.url().should('not.include', '/related-content'); // Adjust the URL as necessary
        cy.get('.notification').should('have.class', 'disabled'); // Adjust the selector as necessary
    });
});
